import { useTranslation } from 'react-i18next';
import {
  Building2,
  Bus,
  Camera,
  Route as RouteIcon,
  ScanFace,
  Shuffle,
  UserCog,
  Users,
} from 'lucide-react';
import { Card, CardContent, SectionHeading } from '@/components/ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { StatCard } from '@/components/common/StatCard';
import { TrendChart } from '@/components/charts/TrendChart';
import { SkeletonStatGrid } from '@/components/ui/skeleton';
import { ErrorState } from '@/components/feedback/states';
import { formatLongDate, formatPercent } from '@/lib/format';
import { useAuth, useIdentity } from '@/features/auth/session';
import { useAdminDashboard } from './api';
import { DashboardActionStrip } from './DashboardActionStrip';

/**
 * Organisation overview.
 *
 * A deliberately focused operational landing page. Deeper organisation data
 * remains available from the navigation instead of competing for attention
 * here.
 */
export default function AdminDashboardPage() {
  const { t } = useTranslation();
  const identity = useIdentity();
  const { activeDepotId, setActiveDepotId } = useAuth();
  const { data, isLoading, isError, error, refetch } = useAdminDashboard(30, activeDepotId);
  const totals = data?.totals;

  return (
    <div className="space-y-9 lg:space-y-11">
      <header className="flex flex-wrap items-start justify-between gap-4 lg:pb-2">
        <div>
          <h1 className="text-3xl font-bold leading-tight tracking-[-0.025em] lg:text-4xl">
            {t('admin.title')}
          </h1>
          <p className="mt-2 text-sm text-muted-foreground lg:text-base">
            {t('admin.subtitle', {
              organisation: identity.organizationName,
              date: formatLongDate(new Date()),
            })}
          </p>
        </div>
        <Select
          value={activeDepotId ?? ''}
          onValueChange={(value) => setActiveDepotId(value || null)}
        >
          <SelectTrigger className="w-full sm:w-56">
            <SelectValue placeholder={t('depots.allDepots')} />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="">{t('depots.allDepots')}</SelectItem>
            {identity.depots.map((depot) => (
              <SelectItem key={depot.id} value={depot.id}>
                {depot.name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </header>

      {isError && <ErrorState error={error} onRetry={() => void refetch()} />}

      <DashboardActionStrip
        title={t('home.quickActions')}
        actions={[
          { to: '/attendance/take', icon: ScanFace, label: t('home.takeAttendance') },
          { to: '/trips/add', icon: Camera, label: t('home.addBusDetails') },
        ]}
      />

      <section>
        <SectionHeading title={t('nav.overview')} />
        {isLoading ? (
          <div className="mt-3">
            <SkeletonStatGrid count={5} />
          </div>
        ) : (
          <div className="mt-3 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-5 lg:gap-4">
            <StatCard
              label={t('admin.activeManagers')}
              value={totals?.managers ?? 0}
              icon={UserCog}
              to="/admin/managers"
              className="lg:min-h-32 lg:p-5"
            />
            <StatCard
              label={t('admin.activeDrivers')}
              value={totals?.drivers ?? 0}
              icon={Users}
              to="/fleet/drivers"
              className="lg:min-h-32 lg:p-5"
            />
            <StatCard
              label={t('admin.activeBuses')}
              value={totals?.buses ?? 0}
              icon={Bus}
              to="/fleet/buses"
              className="lg:min-h-32 lg:p-5"
            />
            <StatCard
              label={t('admin.depots')}
              value={totals?.depots ?? 0}
              icon={Building2}
              to="/admin/depots"
              className="lg:min-h-32 lg:p-5"
            />
            <StatCard
              label={t('admin.routes')}
              value={totals?.routes ?? 0}
              icon={RouteIcon}
              to="/fleet/routes"
              className="lg:min-h-32 lg:p-5"
            />
          </div>
        )}
      </section>

      {/* --- Today ------------------------------------------------------- */}
      <section>
        <SectionHeading title={t('common.today')} />
        {isLoading ? (
          <div className="mt-2">
            <SkeletonStatGrid count={3} />
          </div>
        ) : (
          <div className="mt-3 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 lg:gap-4">
            <StatCard
              label={t('admin.attendanceRate')}
              value={
                data?.attendance_rate_today != null
                  ? formatPercent(data.attendance_rate_today, { decimals: 0 })
                  : '—'
              }
              className="lg:min-h-36 lg:p-6"
              icon={Users}
              to="/attendance"
              tone={
                data?.attendance_rate_today != null && data.attendance_rate_today < 85
                  ? 'warning'
                  : 'success'
              }
            />
            <StatCard
              label={t('admin.busesReadToday')}
              value={totals?.buses_read_today ?? 0}
              sublabel={`${t('admin.activeBuses')}: ${totals?.buses ?? 0}`}
              icon={RouteIcon}
              to="/trips"
              className="lg:min-h-36 lg:p-6"
            />
            <StatCard
              label={t('admin.actingCoverageToday')}
              value={totals?.acting_coverage_today ?? 0}
              icon={Shuffle}
              to="/attendance"
              className="lg:min-h-36 lg:p-6"
            />
          </div>
        )}
      </section>

      <div className="grid items-start gap-8 lg:grid-cols-[minmax(22rem,0.72fr)_minmax(0,1.28fr)] lg:gap-6">
        <section>
          <SectionHeading title={t('admin.fleetAvailability')} />
          <Card className="mt-3">
            <CardContent className="grid grid-cols-2 gap-x-6 gap-y-8 p-5 sm:grid-cols-4 sm:p-6 lg:grid-cols-2 lg:p-7 xl:grid-cols-4">
              {(['AVAILABLE', 'ON_TRIP', 'MAINTENANCE', 'OUT_OF_SERVICE'] as const).map(
                (status) => (
                  <div key={status}>
                    <p className="tabular text-2xl font-bold leading-none">
                      {data?.fleet_availability[status] ?? 0}
                    </p>
                    <p className="mt-2 text-xs text-muted-foreground">
                      {t(`status.bus.${status}`)}
                    </p>
                  </div>
                ),
              )}
            </CardContent>
          </Card>
        </section>

        <TrendChart
          title={t('admin.charts.distance')}
          data={data?.series.distance ?? []}
          kind="bar"
          unitSuffix={t('units.km')}
        />
      </div>
    </div>
  );
}
